{"code": "export async function main(input: unknown) {
  // 1. Sentry issues of project "web"
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const checked = issues.length;

  // 2. unresolved + at least 50 events
  const candidates = issues.filter(i => i.status === "unresolved" && i.count >= 50);

  // 3. those whose culprit no Linear issue mentions yet
  const fresh: typeof candidates = [];
  for (const issue of candidates) {
    const { issues: found } = await sdk.linear.searchIssues({ query: issue.culprit });
    const mentioned = found.some(li =>
      (li.description ?? "").includes(issue.culprit) || (li.title ?? "").includes(issue.culprit)
    );
    if (!mentioned) fresh.push(issue);
  }
  // only the first such Sentry issue is used for the new Linear issue
  const first = fresh[0];

  // 4. GitHub blame of the crashing line
  const blame = await sdk.github.getBlame({ file: first.filename, line: first.lineNumber });

  // 5. create the Linear issue
  const created = await sdk.linear.createIssue({
    title: `[Sentry] ${first.title}`,
    description: first.culprit,
    assigneeEmail: blame.authorEmail,
  });

  return {
    checked,
    created: [created.identifier],
    plan: {
      candidates: candidates.map(i => ({ id: i.id, culprit: i.culprit, count: i.count })),
      freshCulprits: fresh.map(i => i.culprit),
      sentryIssue: first.id,
      blame,
    },
  };
}"}

